{% comment %}
  Selector de color y talla — Custom liquid en la ficha de producto.
  Oculta el picker nativo del tema. Si el viejo sigue visible, oculta ese bloque en el editor del tema.
{% endcomment %}
{% if product %}
<style>
.vp{--vp-ink:#111111;--vp-muted:#6b7280;--vp-line:#e5e7eb;--vp-bg:#fff;font-family:inherit;color:var(--vp-ink);max-width:520px;}
.vp *{box-sizing:border-box;}
.vp-block{margin:0 0 18px;}
.vp-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin:0 0 10px;}
.vp-label{font-size:15px;font-weight:700;letter-spacing:.01em;}
.vp-chosen{font-size:14px;color:var(--vp-muted);font-weight:500;}
.vp-swatches{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;}
.vp-swatch{position:relative;display:block;padding:0;border:none;background:transparent;cursor:pointer;border-radius:12px;}
.vp-swatch img{display:block;width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:10px;background:#f3f4f6;outline:1px solid rgb(0 0 0 / .08);outline-offset:-1px;}
.vp-swatch[aria-checked="true"] img{outline:2px solid var(--vp-ink);outline-offset:2px;}
.vp-swatch:focus-visible{outline:2px solid var(--vp-ink);outline-offset:3px;}
.vp-swatch.is-na{opacity:.38;cursor:not-allowed;}
.vp-pills{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;}
.vp-pill{display:inline-flex;min-height:44px;width:100%;align-items:center;justify-content:center;padding:0 8px;border:1px solid var(--vp-line);border-radius:999px;background:var(--vp-bg);color:var(--vp-ink);font:inherit;font-size:13px;font-weight:600;cursor:pointer;text-align:center;}
.vp-pill[aria-checked="true"]{background:var(--vp-ink);color:#fff;border-color:var(--vp-ink);}
.vp-pill.is-na{opacity:.35;text-decoration:line-through;cursor:not-allowed;}
.vp-pill:focus-visible{outline:2px solid var(--vp-ink);outline-offset:2px;}
@media(max-width:360px){.vp-swatches{gap:6px;}.vp-pill{padding:0 4px;font-size:12px;}}
variant-selects,
variant-radios,
fieldset.product-form__input,
.product-form__input:has(input[type="radio"]),
.product-form__input:has(select){display:none!important;}
</style>
<div class="vp" id="vp-{{ product.id }}" data-current="{{ product.selected_or_first_available_variant.id }}">
  {% for option in product.options_with_values %}
    {% assign n = option.name | downcase %}
    {% assign is_color = false %}
    {% if n == 'color' or n == 'colour' or n contains 'color' %}{% assign is_color = true %}{% endif %}
    {% assign opt_pos = option.position %}
    <div class="vp-block" data-option="{{ option.name | escape }}" data-position="{{ opt_pos }}">
      <div class="vp-head">
        <span class="vp-label">{{ option.name }}</span>
        <span class="vp-chosen" data-chosen>{{ option.selected_value }}</span>
      </div>
      {% if is_color %}
        <div class="vp-swatches" role="radiogroup" aria-label="{{ option.name | escape }}">
          {% for value in option.values %}
            {% assign vp_src = '' %}
            {% for v in product.variants %}
              {% if vp_src == '' %}
                {% if opt_pos == 1 and v.option1 == value and v.featured_image %}
                  {% assign vp_src = v.featured_image | image_url: width: 240 %}
                {% elsif opt_pos == 2 and v.option2 == value and v.featured_image %}
                  {% assign vp_src = v.featured_image | image_url: width: 240 %}
                {% elsif opt_pos == 3 and v.option3 == value and v.featured_image %}
                  {% assign vp_src = v.featured_image | image_url: width: 240 %}
                {% endif %}
              {% endif %}
            {% endfor %}
            <button type="button" class="vp-swatch" role="radio" data-value="{{ value | escape }}" aria-checked="{% if option.selected_value == value %}true{% else %}false{% endif %}" aria-label="{{ value | escape }}">
              {% if vp_src != '' %}
                <img src="{{ vp_src }}" alt="{{ value | escape }}" width="80" height="80" loading="lazy">
              {% else %}
                <img src="{{ product.featured_image | image_url: width: 240 }}" alt="{{ value | escape }}" width="80" height="80" loading="lazy">
              {% endif %}
            </button>
          {% endfor %}
        </div>
      {% else %}
        <div class="vp-pills" role="radiogroup" aria-label="{{ option.name | escape }}">
          {% for value in option.values %}
            <button type="button" class="vp-pill" role="radio" data-value="{{ value | escape }}" aria-checked="{% if option.selected_value == value %}true{% else %}false{% endif %}">{{ value }}</button>
          {% endfor %}
        </div>
      {% endif %}
    </div>
  {% endfor %}
  <script type="application/json" id="vp-json-{{ product.id }}">{{ product | json }}</script>
</div>
<script>
(function(){
  var root = document.getElementById("vp-{{ product.id }}");
  if(!root || root.getAttribute("data-vp-ready")) return;
  root.setAttribute("data-vp-ready","1");
  var dataEl = document.getElementById("vp-json-{{ product.id }}");
  var product = JSON.parse(dataEl.textContent);
  var blocks = [].slice.call(root.querySelectorAll(".vp-block"));
  var current = null;
  function choices(){
    return blocks.map(function(b){
      var on = b.querySelector('[aria-checked="true"]');
      return on ? on.getAttribute("data-value") : "";
    });
  }
  function findVariant(ch){
    return (product.variants || []).find(function(v){
      var opts = v.options || [v.option1, v.option2, v.option3];
      return ch.every(function(val, i){ return String(opts[i]||"") === String(val); });
    }) || null;
  }
  function availableFor(index, value){
    var ch = choices();
    ch[index] = value;
    var v = findVariant(ch);
    return !!(v && v.available);
  }
  function applyId(id){
    if(!id) return;
    var sid = String(id);
    var nodes = document.querySelectorAll(
      'form[action*="/cart/add"] [name="id"], form[action*="/cart/add.js"] [name="id"], .product-variant-id, product-form [name="id"], [data-product-id="{{ product.id }}"] [name="id"]'
    );
    [].forEach.call(nodes, function(input){
      input.value = sid;
      input.setAttribute("value", sid);
      try { input.dispatchEvent(new Event("input", { bubbles: true })); } catch(e){}
      try { input.dispatchEvent(new Event("change", { bubbles: true })); } catch(e){}
    });
    var box = document.querySelector(".product-form__variants");
    if(box && current) box.setAttribute("data-values", current.title || "");
    var pickup = document.querySelector("pickup-availability");
    if(pickup) pickup.setAttribute("data-variant-id", sid);
  }
  function paint(){
    blocks.forEach(function(b, i){
      [].slice.call(b.querySelectorAll("[data-value]")).forEach(function(btn){
        var val = btn.getAttribute("data-value");
        btn.classList.toggle("is-na", !availableFor(i, val));
      });
    });
    current = findVariant(choices());
    if(current){
      applyId(current.id);
      try {
        var path = window.location.pathname;
        history.replaceState({}, "", path + "?variant=" + current.id);
      } catch(e){}
    }
    document.dispatchEvent(new CustomEvent("variant:change", { detail: { variant: current, product: product }, bubbles: true }));
  }
  function patchBody(body){
    if(!current) return body;
    var id = String(current.id);
    try {
      if(body instanceof FormData){
        body.set("id", id);
        if(body.has("items[0]id")) body.set("items[0]id", id);
        return body;
      }
      if(typeof URLSearchParams !== "undefined" && body instanceof URLSearchParams){
        body.set("id", id);
        return body;
      }
      if(typeof body === "string"){
        if(body.charAt(0) === "{"){
          var json = JSON.parse(body);
          if(json.id) json.id = current.id;
          if(json.items && json.items[0]) json.items[0].id = current.id;
          return JSON.stringify(json);
        }
        if(/(^|&)id=/.test(body)) return body.replace(/(^|&)id=d+/, "$1id=" + id);
        return body + (body ? "&" : "") + "id=" + id;
      }
    } catch(e){}
    return body;
  }
  function isCartAdd(url){
    if(!url) return false;
    var u = String(url);
    return u.indexOf("/cart/add") !== -1;
  }
  if(window.fetch){
    var origFetch = window.fetch;
    window.fetch = function(input, init){
      var url = typeof input === "string" ? input : (input && input.url);
      if(isCartAdd(url) && current){
        init = init ? Object.assign({}, init) : {};
        if(init.body) init.body = patchBody(init.body);
      }
      return origFetch.call(this, input, init);
    };
  }
  if(window.XMLHttpRequest){
    var origOpen = XMLHttpRequest.prototype.open;
    var origSend = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.open = function(method, url){
      this._vpCart = isCartAdd(url);
      return origOpen.apply(this, arguments);
    };
    XMLHttpRequest.prototype.send = function(body){
      if(this._vpCart && current && body) body = patchBody(body);
      return origSend.call(this, body);
    };
  }
  document.addEventListener("submit", function(e){
    var form = e.target;
    if(!form || !form.getAttribute) return;
    if(!isCartAdd(form.getAttribute("action") || form.action || "")) return;
    paint();
    if(current){
      var input = form.querySelector('[name="id"]');
      if(!input){
        input = document.createElement("input");
        input.type = "hidden";
        input.name = "id";
        form.appendChild(input);
      }
      input.value = String(current.id);
      input.setAttribute("value", String(current.id));
    }
  }, true);
  document.addEventListener("click", function(e){
    var btn = e.target && e.target.closest && e.target.closest('[name="add"], .product-form__submit, .main-product-atc, button[type="submit"]');
    if(!btn) return;
    var form = btn.form || btn.closest("form") || btn.closest("product-form");
    if(!form) return;
    var action = (form.getAttribute && form.getAttribute("action")) || form.action || "";
    if(form.tagName === "PRODUCT-FORM" || isCartAdd(action)) paint();
  }, true);
  blocks.forEach(function(b, i){
    b.addEventListener("click", function(e){
      var btn = e.target.closest("[data-value]");
      if(!btn || !b.contains(btn)) return;
      if(btn.classList.contains("is-na") && btn.classList.contains("vp-pill")) return;
      [].slice.call(b.querySelectorAll("[data-value]")).forEach(function(x){ x.setAttribute("aria-checked", "false"); });
      btn.setAttribute("aria-checked", "true");
      var chosen = b.querySelector("[data-chosen]");
      if(chosen) chosen.textContent = btn.getAttribute("data-value");
      var ch = choices();
      var v = findVariant(ch);
      if(!v || !v.available){
        var sizeBlock = blocks.find(function(bb){ return bb !== b && bb.querySelector(".vp-pill"); });
        if(sizeBlock){
          var pills = [].slice.call(sizeBlock.querySelectorAll(".vp-pill"));
          var si = blocks.indexOf(sizeBlock);
          for(var p=0;p<pills.length;p++){
            var tryCh = ch.slice();
            tryCh[si] = pills[p].getAttribute("data-value");
            var tv = findVariant(tryCh);
            if(tv && tv.available){
              pills.forEach(function(x){ x.setAttribute("aria-checked","false"); });
              pills[p].setAttribute("aria-checked","true");
              var c2 = sizeBlock.querySelector("[data-chosen]");
              if(c2) c2.textContent = pills[p].getAttribute("data-value");
              break;
            }
          }
        }
      }
      paint();
    });
  });
  if(document.readyState === "loading") document.addEventListener("DOMContentLoaded", paint);
  else paint();
})();
</script>
{% endif %}

{% if product %}
{% assign current_variant = product.selected_or_first_available_variant %}

<style>
  .hc-atc {
    --hc-bg: #4489E9;
    --hc-bg-hover: #2E8FF0;
    --hc-bg-disabled: #B7D7F5;
    --hc-text: #ffffff;
    width: 100%;
    margin: 8px 0 0;
  }
  .hc-atc__btn {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    min-height: 56px;
    padding: 14px 18px;
    border: 0;
    border-radius: 14px;
    background: var(--hc-bg);
    color: var(--hc-text);
    font-family: inherit;
    font-size: 16px;
    font-weight: 700;
    letter-spacing: 0.02em;
    cursor: pointer;
  }
  .hc-atc__btn:hover:not(:disabled) { background: var(--hc-bg-hover); }
  .hc-atc__btn:disabled { background: var(--hc-bg-disabled); cursor: not-allowed; }
  .hc-atc__label { text-transform: uppercase; }
  .hc-atc__prices { display: flex; align-items: baseline; gap: 8px; white-space: nowrap; }
  .hc-atc__price { font-weight: 800; }
  .hc-atc__compare { font-weight: 600; opacity: .75; text-decoration: line-through; }
  .hc-atc__msg { margin: 8px 0 0; font-size: 13px; color: #c0392b; display: none; }
</style>

<div class="hc-atc" data-hc-atc>
  <button type="button" class="hc-atc__btn" data-hc-atc-btn {% unless current_variant.available %}disabled{% endunless %}>
    <span class="hc-atc__label" data-hc-atc-label>
      {% if current_variant.available %}Agregar al carrito{% else %}Agotado{% endif %}
    </span>
    <span class="hc-atc__prices">
      <span class="hc-atc__price" data-hc-atc-price>{{ current_variant.price | money_without_trailing_zeros }}</span>
      <span class="hc-atc__compare" data-hc-atc-compare {% unless current_variant.compare_at_price > current_variant.price %}style="display:none"{% endunless %}>
        {% if current_variant.compare_at_price > current_variant.price %}{{ current_variant.compare_at_price | money_without_trailing_zeros }}{% endif %}
      </span>
    </span>
  </button>
  <p class="hc-atc__msg" data-hc-atc-msg></p>
</div>

<script>
(function () {
  const root = document.querySelector('[data-hc-atc]');
  if (!root) return;

  const btn = root.querySelector('[data-hc-atc-btn]');
  const label = root.querySelector('[data-hc-atc-label]');
  const priceEl = root.querySelector('[data-hc-atc-price]');
  const compareEl = root.querySelector('[data-hc-atc-compare]');
  const msg = root.querySelector('[data-hc-atc-msg]');

  const optionNames = {{ product.options | json }};
  const variants = {{ product.variants | json }};
  const moneyFormat = {{ shop.money_format | json }};
  const fallbackId = {{ current_variant.id }};

  function formatMoney(cents) {
    if (window.Shopify && Shopify.formatMoney) {
      return Shopify.formatMoney(cents, moneyFormat).replace(',00', '').replace('.00', '');
    }
    return '$' + Math.round(Number(cents) / 100).toLocaleString('es-CL');
  }

  function norm(str) {
    return String(str || '')
      .trim()
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '');
  }

  function getOptionValue(optionName, index) {
    const name = optionName;
    const pos = index + 1;

    const radioNamed = document.querySelector('input[type="radio"][name="options[' + name + ']"]:checked');
    if (radioNamed) return radioNamed.value;

    const selectNamed = document.querySelector('select[name="options[' + name + ']"]');
    if (selectNamed && selectNamed.value) return selectNamed.value;

    const radioIndex = document.querySelector('input[type="radio"][data-index="option' + pos + '"]:checked');
    if (radioIndex) return radioIndex.value;

    const selectIndex = document.querySelector('select[data-index="option' + pos + '"]');
    if (selectIndex && selectIndex.value) return selectIndex.value;

    const selectedSwatch = document.querySelector(
      '.product-form__input input[type="radio"][name*="' + name + '"]:checked,' +
      '[data-option-name="' + name + '"].selected,' +
      '[data-option="' + name + '"] .selected,' +
      '[data-option-index="' + index + '"] .selected,' +
      '[data-option-index="' + index + '"] [aria-checked="true"],' +
      '[data-option-index="' + index + '"] [aria-pressed="true"]'
    );
    if (selectedSwatch) {
      return selectedSwatch.getAttribute('data-value') || selectedSwatch.value || selectedSwatch.textContent;
    }

    const labels = Array.from(document.querySelectorAll('fieldset, .product-form__input, .variant-picker, .swatch-wrapper'));
    for (const box of labels) {
      const title = (box.querySelector('legend, label, .form__label, .variant-picker__label') || {}).textContent || '';
      if (norm(title).indexOf(norm(name)) === -1) continue;
      const chosen = box.querySelector('input:checked, .selected, [aria-checked="true"], [aria-pressed="true"], [aria-current="true"]');
      if (chosen) {
        return chosen.getAttribute('data-value') || chosen.value || chosen.getAttribute('title') || chosen.textContent;
      }
    }
    return null;
  }

  function variantFromOptions() {
    const selected = optionNames.map((name, i) => getOptionValue(name, i));
    if (selected.every(v => !v)) return null;

    return variants.find(function (variant) {
      return optionNames.every(function (name, i) {
        if (!selected[i]) return true;
        const wanted = norm(selected[i]);
        const a = norm(variant.options && variant.options[i]);
        const b = norm(variant['option' + (i + 1)]);
        return wanted === a || wanted === b || a.indexOf(wanted) !== -1 || wanted.indexOf(a) !== -1;
      });
    }) || null;
  }

  function variantFromUrl() {
    const id = Number(new URLSearchParams(window.location.search).get('variant'));
    if (!id) return null;
    return variants.find(v => Number(v.id) === id) || null;
  }

  function variantFromHiddenInput() {
    const inputs = Array.from(document.querySelectorAll('form[action*="/cart/add"] [name="id"], [name="id"]'));
    const live = inputs.filter(function (el) {
      if (el.disabled) return false;
      if (el.closest('noscript')) return false;
      if (el.tagName === 'SELECT' && el.options && el.options.length > 8) return false;
      return !!el.value;
    });
    const last = live[live.length - 1];
    if (!last) return null;
    return variants.find(v => String(v.id) === String(last.value)) || null;
  }

  function getCurrentVariant() {
    return variantFromOptions() || variantFromUrl() || variantFromHiddenInput() ||
      variants.find(v => Number(v.id) === Number(fallbackId)) || variants[0];
  }

  function getQuantity() {
    const qty = document.querySelector('form[action*="/cart/add"] [name="quantity"], input[name="quantity"]');
    const n = qty ? parseInt(qty.value, 10) : 1;
    return n > 0 ? n : 1;
  }

  function paint(variant) {
    if (!variant) return;
    priceEl.textContent = formatMoney(variant.price);
    if (variant.compare_at_price && variant.compare_at_price > variant.price) {
      compareEl.textContent = formatMoney(variant.compare_at_price);
      compareEl.style.display = '';
    } else {
      compareEl.style.display = 'none';
    }
    if (variant.available) {
      btn.disabled = false;
      if (label.textContent !== 'Agregando...') label.textContent = 'Agregar al carrito';
    } else {
      btn.disabled = true;
      label.textContent = 'Agotado';
    }
  }

  async function openCartDrawer(addJson) {
    const drawer = document.querySelector('cart-drawer');
    if (drawer) {
      try {
        drawer.classList.remove('is-empty');
        if (typeof drawer.renderContents === 'function' && addJson) drawer.renderContents(addJson);
        if (typeof drawer.open === 'function') { drawer.open(); return; }
        if (typeof drawer.show === 'function') { drawer.show(); return; }
      } catch (e) {}
    }
    document.dispatchEvent(new CustomEvent('cart:refresh', { bubbles: true }));
    document.dispatchEvent(new CustomEvent('cart:updated', { bubbles: true }));
    const icon = document.querySelector('#cart-icon-bubble, a[href="/cart"], .header__icon--cart');
    if (icon) icon.click();
  }

  async function addToCart() {
    msg.style.display = 'none';
    const variant = getCurrentVariant();
    if (!variant) {
      msg.textContent = 'Elige una variante primero';
      msg.style.display = 'block';
      return;
    }
    if (!variant.available) {
      msg.textContent = 'Esta variante está agotada';
      msg.style.display = 'block';
      return;
    }

    btn.disabled = true;
    label.textContent = 'Agregando...';

    const formData = new FormData();
    formData.append('id', String(variant.id));
    formData.append('quantity', String(getQuantity()));

    const drawer = document.querySelector('cart-drawer');
    if (drawer && typeof drawer.getSectionsToRender === 'function') {
      formData.append('sections', drawer.getSectionsToRender().map(s => s.id).join(','));
      formData.append('sections_url', window.location.pathname);
    }

    try {
      const response = await fetch((window.Shopify && Shopify.routes && Shopify.routes.root ? Shopify.routes.root : '/') + 'cart/add.js', {
        method: 'POST',
        headers: { 'X-Requested-With': 'XMLHttpRequest' },
        body: formData
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.description || 'No se pudo agregar al carrito');
      await openCartDrawer(data);
    } catch (error) {
      msg.textContent = error.message || 'No se pudo agregar al carrito';
      msg.style.display = 'block';
    } finally {
      label.textContent = 'Agregar al carrito';
      paint(getCurrentVariant());
    }
  }

  function refresh() { paint(getCurrentVariant()); }

  btn.addEventListener('click', function () {
    setTimeout(addToCart, 80);
  });

  document.addEventListener('change', function () { setTimeout(refresh, 50); });
  document.addEventListener('click', function () { setTimeout(refresh, 80); });
  window.addEventListener('popstate', refresh);
  document.addEventListener('shopify:variant:change', refresh);
  document.addEventListener('variant:change', refresh);
  document.addEventListener('theme:variant:change', refresh);

  refresh();
})();
</script>
{% endif %}

